import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import { useEffect } from "react";

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => { window.scrollTo(0, 0); }, [pathname]);
  return null;
}
import { LanguageProvider } from "./context/LanguageContext";
import { AuthProvider } from "./context/AuthContext";
import { ShopProvider } from "./context/ShopContext";
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";
import Home from "./pages/Home";
import Cart from "./pages/Cart";
import Gallery from "./pages/Gallery";
import About from "./pages/About";
import Login from "./pages/Login";
import Admin from "./pages/Admin";
import Shop from "./pages/Shop";
import ProductDetails from "./pages/ProductDetails";
import UserDashboard from "./pages/UserDashboard";
import GoogleCallback from "./pages/GoogleCallback";
import Configurator from "./pages/Configurator";

function App() {
  return (
    <Router>
      <ScrollToTop />
      <LanguageProvider>
        <AuthProvider>
          <ShopProvider>
            <div className="min-h-screen flex flex-col font-sans text-slate-800">
              <Navbar />
              <main className="flex-grow">
                <Routes>
                  <Route path="/" element={<Home />} />
                  <Route path="/product/:id" element={<ProductDetails />} />
                  <Route path="/cart" element={<Cart />} />
                  <Route path="/shop" element={<Shop />} />
                  <Route path="/gallery" element={<Gallery />} />
                  <Route path="/about" element={<About />} />
                  <Route path="/login" element={<Login />} />
                  <Route path="/admin" element={<Admin />} />
                  <Route path="/dashboard" element={<UserDashboard />} />
                  <Route path="/auth/google/callback" element={<GoogleCallback />} />
                  <Route path="/configurator" element={<Configurator />} />
                </Routes>
              </main>
              <Footer />
            </div>
          </ShopProvider>
        </AuthProvider>
      </LanguageProvider>
    </Router>
  );
}

export default App;

import { Link, useNavigate } from "react-router-dom";
import { ShoppingCart, Menu, X, Globe, LogOut, User } from "lucide-react";
import { useState, useEffect } from "react";
import { useLanguage } from "../context/LanguageContext";
import { useAuth } from "../context/AuthContext";
import { useShop } from "../context/ShopContext";

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const { lang, toggleLanguage, t } = useLanguage();
  const { user, authLoading, logout } = useAuth();
  const navigate = useNavigate();
  const { cart } = useShop();
  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  const [updateCount, setUpdateCount] = useState(0);

  useEffect(() => {
    if (authLoading || !user || user.role === "admin") {
      setUpdateCount(0);
      return;
    }

    const checkUpdates = async () => {
      try {
        const emailEnc = encodeURIComponent(user.email);

        const [ordersRes, messagesRes, configRes] = await Promise.all([
          fetch(`/api/orders/user/${emailEnc}`, { credentials: "include" }).then((r) => r.ok ? r.json() : []),
          fetch(`/api/messages/user/${emailEnc}`, { credentials: "include" }).then((r) => r.ok ? r.json() : []),
          fetch(`/api/configurator-inquiries/user/${emailEnc}`, { credentials: "include" }).then((r) => r.ok ? r.json() : []),
        ]);

        let totalCount = 0;

        // 1. Check orders
        const ordersKey = `read_orders_status_${user.email}`;
        let storedStatuses = {};
        try {
          storedStatuses = JSON.parse(localStorage.getItem(ordersKey)) || {};
        } catch (e) {}
        const isFirstOrdersLoad = Object.keys(storedStatuses).length === 0;
        if (!isFirstOrdersLoad) {
          ordersRes.forEach((o) => {
            const prevStatus = storedStatuses[o.id];
            if (!prevStatus || prevStatus !== o.status) {
              totalCount++;
            }
          });
        }

        // 2. Check messages
        const msgKey = `seen_messages_replies_${user.email}`;
        let storedMsgReplies = {};
        try {
          storedMsgReplies = JSON.parse(localStorage.getItem(msgKey)) || {};
        } catch (e) {}
        messagesRes.forEach((m) => {
          if (m.reply) {
            const prevReply = storedMsgReplies[m.id];
            if (prevReply !== m.reply) {
              totalCount++;
            }
          }
        });

        // 3. Check configurator inquiries
        const configKey = `seen_config_replies_${user.email}`;
        let storedConfigReplies = {};
        try {
          storedConfigReplies = JSON.parse(localStorage.getItem(configKey)) || {};
        } catch (e) {}
        configRes.forEach((inq) => {
          if (inq.reply) {
            const prevReply = storedConfigReplies[inq.id];
            if (prevReply !== inq.reply) {
              totalCount++;
            }
          }
        });

        setUpdateCount(totalCount);
      } catch (err) {
        console.error("Failed to check navbar updates:", err);
      }
    };

    checkUpdates();
    // Re-check every 30 seconds or on window focus
    const interval = setInterval(checkUpdates, 30000);
    window.addEventListener("focus", checkUpdates);
    window.addEventListener("dashboard-updates-read", checkUpdates);
    return () => {
      clearInterval(interval);
      window.removeEventListener("focus", checkUpdates);
      window.removeEventListener("dashboard-updates-read", checkUpdates);
    };
  }, [user, authLoading]);

  return (
    <nav className="sticky top-0 z-50 h-[70px] flex items-center bg-white shadow-sm">
      <div className="container mx-auto px-4 flex justify-between items-center w-full">
        <Link
          to="/"
          className="text-2xl font-extrabold text-black no-underline"
        >
          Carbon<span className="text-primary">.ez</span>
        </Link>

        <div className="hidden md:flex gap-8 font-medium text-secondary">
          <Link to="/" className="hover:text-primary transition-colors">
            {t("nav", "home")}
          </Link>
          <Link
            to="/shop"
            className="hover:text-primary transition-colors"
            onClick={() => sessionStorage.removeItem("shopScrollY")}
          >
            {t("nav", "shop")}
          </Link>
          <Link to="/gallery" className="hover:text-primary transition-colors">
            {t("nav", "gallery")}
          </Link>
          <Link to="/configurator" className="hover:text-primary transition-colors">
            {t("nav", "configurator")}
          </Link>
          <Link to="/about" className="hover:text-primary transition-colors">
            {t("nav", "about")}
          </Link>
          {user?.role === "admin" && (
            <Link
              to="/admin"
              className="text-primary font-bold hover:text-yellow-400"
            >
              {t("nav", "admin")}
            </Link>
          )}
        </div>

        <div className="hidden md:flex items-center gap-6">
          <button
            onClick={toggleLanguage}
            className="flex items-center text-secondary hover:text-primary transition-colors"
            title="Switch Language"
          >
            <Globe size={20} />
            <span className="ml-[5px] text-xs font-bold">
              {lang.toUpperCase()}
            </span>
          </button>

          <Link
            to="/cart"
            className="relative flex items-center text-secondary hover:text-primary transition-colors"
          >
            <ShoppingCart size={20} />
            {cartCount > 0 && (
              <span className="absolute -top-2 -right-2 bg-accent text-primary text-[0.7rem] w-[18px] h-[18px] rounded-full flex items-center justify-center font-bold">
                {cartCount}
              </span>
            )}
          </Link>

          {user?.role !== "admin" && (
            <Link
              to="/dashboard"
              className="flex items-center gap-1.5 text-secondary hover:text-primary transition-colors font-semibold text-sm"
              title="My Account"
            >
              <User size={20} />
              <span>{user ? user.name : t("nav", "myAccount")}</span>
              {updateCount > 0 && (
                <span className="ml-1 bg-black text-primary text-[10px] font-bold rounded-full w-4 h-4 flex items-center justify-center">
                  {updateCount}
                </span>
              )}
            </Link>
          )}

          {user && (
            <button
              onClick={() => { logout(); navigate("/login"); }}
              className="flex items-center text-secondary hover:text-primary transition-colors"
              title={t("nav", "logout")}
            >
              <LogOut size={20} />
            </button>
          )}
        </div>

        <button
          className="md:hidden text-secondary"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {isOpen && (
        <div className="md:hidden absolute top-[70px] left-0 w-full bg-white shadow-md border-t border-gray-100 flex flex-col p-5 gap-4">
          <Link
            to="/"
            className="text-lg py-2 border-b border-gray-100"
            onClick={() => setIsOpen(false)}
          >
            {t("nav", "home")}
          </Link>
          <Link
            to="/shop"
            className="text-lg py-2 border-b border-gray-100"
            onClick={() => {
              setIsOpen(false);
              sessionStorage.removeItem("shopScrollY");
            }}
          >
            {t("nav", "shop")}
          </Link>
          <Link
            to="/gallery"
            className="text-lg py-2 border-b border-gray-100"
            onClick={() => setIsOpen(false)}
          >
            {t("nav", "gallery")}
          </Link>
          <Link
            to="/configurator"
            className="text-lg py-2 border-b border-gray-100"
            onClick={() => setIsOpen(false)}
          >
            {t("nav", "configurator")}
          </Link>
          <Link
            to="/about"
            className="text-lg py-2 border-b border-gray-100"
            onClick={() => setIsOpen(false)}
          >
            {t("nav", "about")}
          </Link>
          {user?.role === "admin" && (
            <Link
              to="/admin"
              className="text-lg py-2 border-b border-gray-100 text-primary font-bold"
              onClick={() => setIsOpen(false)}
            >
              {t("nav", "admin")}
            </Link>
          )}

          <div className="flex flex-col gap-3 mt-2">
            <button
              onClick={toggleLanguage}
              className="flex items-center gap-2 py-2"
            >
              <Globe size={18} /> {lang === "bs" ? "Jezik" : "Language"}: {lang.toUpperCase()}
            </button>

            <Link
              to="/cart"
              onClick={() => setIsOpen(false)}
              className="flex items-center gap-2 py-2"
            >
              <ShoppingCart size={18} /> {t("nav", "cart")} ({cartCount})
            </Link>

            {user?.role !== "admin" && (
              <Link
                to="/dashboard"
                onClick={() => setIsOpen(false)}
                className="flex items-center gap-2 py-2 font-bold text-primary"
              >
                <User size={18} />
                {user ? `My Account (${user.name})` : t("nav", "myAccount")}
                {updateCount > 0 && (
                  <span className="ml-1.5 bg-black text-primary text-[10px] font-bold rounded-full w-4 h-4 flex items-center justify-center">
                    {updateCount}
                  </span>
                )}
              </Link>
            )}
            {user && (
              <button
                onClick={() => { logout(); setIsOpen(false); navigate("/login"); }}
                className="text-left font-semibold py-2 text-secondary"
              >
                {t("nav", "logout")}
              </button>
            )}
          </div>
        </div>
      )}
    </nav>
  );
}

import { Plus, Check } from "lucide-react";
import { Link } from "react-router-dom";
import { useShop } from "../context/ShopContext";
import { useLanguage } from "../context/LanguageContext";
import { useAuth } from "../context/AuthContext";
import { useState } from "react";
import { getImageUrl } from "../utils/imageUrl";

export default function ProductCard({ product }) {
  const { addToCart } = useShop();
  const { lang, t } = useLanguage();
  const { user } = useAuth();
  const [added, setAdded] = useState(false);
  const handleAdd = () => {
    addToCart(product);
    setAdded(true);
    setTimeout(() => setAdded(false), 2000);
  };
  const name = lang === "bs" ? (product.nameBs || product.name) : product.name;
  const isAdmin = user?.role === "admin";
  return (
    <div className="bg-white border border-gray-200 rounded-lg overflow-hidden transition-shadow hover:shadow-md group">
      <Link
        to={`/product/${product.id}`}
        className="block h-[350px] overflow-hidden relative"
        onClick={() => sessionStorage.setItem("shopScrollY", window.scrollY.toString())}
      >
        <img
          src={getImageUrl(product.image)}
          alt={name}
          className="w-full h-full object-cover"
        />
        {product.is_in_stock === false && (
          <div className="absolute top-4 left-4 bg-red-600 text-white font-bold text-xs uppercase px-3 py-1.5 rounded-full shadow-lg z-10">
            {t("shop", "outOfStock")}
          </div>
        )}
      </Link>
      <div className="p-5">
        <Link
          to={`/product/${product.id}`}
          className="block"
          onClick={() => sessionStorage.setItem("shopScrollY", window.scrollY.toString())}
        >
          <h3 className="text-lg font-semibold mb-2 text-gray-800 hover:text-primary transition-colors">
            {name}
          </h3>
        </Link>
        <p className="text-xl font-bold text-primary mb-4">
          €{Number(product.price).toFixed(2)}
        </p>
        {!isAdmin && (
          <button
            onClick={handleAdd}
            disabled={product.is_in_stock === false}
            className={`w-full flex items-center justify-center gap-2 py-2 px-4 rounded transition-colors ${
              product.is_in_stock === false
                ? "bg-gray-200 text-gray-500 cursor-not-allowed"
                : added
                ? "bg-green-500 text-white hover:bg-green-600"
                : "bg-primary text-black hover:bg-yellow-400"
            }`}
          >
            {product.is_in_stock === false ? (
              <span>{t("shop", "outOfStock")}</span>
            ) : (
              <>
                {added ? <Check size={18} /> : <Plus size={18} />}
                <span>{added ? "Added" : t("shop", "addToCart")}</span>
              </>
            )}
          </button>
        )}
      </div>
    </div>
  );
}

import { useConfigurator } from '../../context/ConfiguratorContext';
import { useLanguage } from '../../context/LanguageContext';
import { ringColours, threadColours } from '../../data/configuratorConstants';


const topOptions    = ['smooth', 'alcantara', 'perforated', 'carbon'];
const sideOptions   = ['smooth', 'alcantara', 'perforated'];
const bottomOptions = ['smooth', 'alcantara', 'perforated', 'carbon'];

function MaterialSelector({ label, options, value, actionType, highlight, stretch = true, equalWidth = false, className = 'mb-6' }) {
  const { dispatch } = useConfigurator();
  const { t } = useLanguage();

  return (
    <div className={`${className} transition-all duration-300`}>
      <p className={`text-sm font-semibold uppercase tracking-wide mb-2 transition-all duration-300 border-l-[3px] pl-2 ${highlight ? 'border-primary' : 'border-transparent'}`}>{label}</p>
      <div
        className={equalWidth ? 'grid w-max gap-2' : 'flex flex-wrap gap-2'}
        style={equalWidth ? { gridTemplateColumns: `repeat(${options.length}, 1fr)` } : {}}
      >
        {options.map(option => (
          <button
            key={option}
            onClick={() => dispatch({ type: actionType, value: option })}
            className={`${equalWidth ? 'w-full' : stretch ? 'flex-1' : ''} px-4 py-2 rounded border text-sm capitalize transition-colors
              ${value === option
                ? 'bg-black text-white border-black'
                : 'bg-white text-black border-gray-300 hover:border-black'
              }`}
          >
            {t('configurator', option)}
          </button>
        ))}
      </div>
    </div>
  );
}

export default function OptionsPanel({ onOpenInquiry, activeZone }) {
  const { state, dispatch } = useConfigurator();
  const { t } = useLanguage();

  return (
    <div className="p-6">
      {/* Wheel shape */}
      <div className="mb-6">
        <p className={`text-sm font-semibold uppercase tracking-wide mb-2 transition-all duration-300 border-l-[3px] pl-2 ${activeZone === 'hub' ? 'border-primary' : 'border-transparent'}`}>{t('configurator', 'wheelType')}</p>
        <div className="flex flex-wrap gap-2">
          {['factory', 'flat', 'full'].map(shape => (
            <button
              key={shape}
              onClick={() => dispatch({ type: 'SET_WHEEL_SHAPE', value: shape })}
              className={`px-4 py-2 rounded border text-sm capitalize transition-colors
                ${state.wheelShape === shape
                  ? 'bg-black text-white border-black'
                  : 'bg-white text-black border-gray-300 hover:border-black'
                }`}
            >
              {t('configurator', shape)}
            </button>
          ))}
        </div>
      </div>

      {/* Top + Bottom side by side */}
      <div className="grid grid-cols-2 gap-8 mb-6">
        <MaterialSelector label={t('configurator', 'top')}    options={topOptions}    value={state.topMaterial}    actionType="SET_TOP"    highlight={activeZone === 'top'}    className="" />
        <MaterialSelector label={t('configurator', 'bottom')} options={bottomOptions} value={state.bottomMaterial} actionType="SET_BOTTOM" highlight={activeZone === 'bottom'} className="" />
      </div>

      <MaterialSelector label={t('configurator', 'sides')} options={sideOptions} value={state.sideMaterial} actionType="SET_SIDE" highlight={activeZone === 'sides'} equalWidth />

      {/* Ring toggle + colour */}
      <div className="mb-6">
        <p className="text-sm font-semibold uppercase tracking-wide mb-2 border-l-[3px] border-transparent pl-2">{t('configurator', 'ring')}</p>
        <div className="flex items-center gap-3 flex-wrap">
          <button
            onClick={() => dispatch({ type: 'SET_RING', value: !state.ringEnabled })}
            className={`px-4 py-2 rounded border text-sm transition-colors shrink-0
              ${state.ringEnabled
                ? 'bg-black text-white border-black'
                : 'bg-white text-black border-gray-300 hover:border-black'
              }`}
          >
            {state.ringEnabled ? t('configurator', 'removeRing') : t('configurator', 'addRing')}
          </button>
          {state.ringEnabled && (
            <div className="flex gap-2 flex-wrap">
              {ringColours.map(colour => (
                <button
                  key={colour}
                  title={colour.charAt(0).toUpperCase() + colour.slice(1)}
                  onClick={() => dispatch({ type: 'SET_RING_COLOUR', value: colour })}
                  className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110
                    ${state.ringColour === colour ? 'border-black scale-110' : colour === 'white' ? 'border-gray-300' : 'border-transparent'}`}
                  style={{ backgroundColor: colour }}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Thread colour picker */}
      <div className="mb-6">
        <p className="text-sm font-semibold uppercase tracking-wide mb-2 border-l-[3px] border-transparent pl-2">{t('configurator', 'stitching')}</p>
        <div className="flex gap-2 flex-wrap">
          {threadColours.map(colour => (
            <button
              key={colour}
              title={colour.charAt(0).toUpperCase() + colour.slice(1)}
              onClick={() => dispatch({ type: 'SET_THREAD', value: colour })}
              className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110
                ${state.threadColour === colour ? 'border-black scale-110' : colour === 'white' ? 'border-gray-300' : 'border-transparent'}`}
              style={{ backgroundColor: colour }}
            />
          ))}
        </div>
      </div>

      <button
        onClick={onOpenInquiry}
        className="w-full bg-primary hover:bg-yellow-400 text-black font-extrabold uppercase tracking-wider py-4 px-6 rounded-xl transition-all duration-300 transform hover:-translate-y-0.5 shadow-md flex items-center justify-center gap-2 mt-8"
      >
        {t('configurator', 'inquiryButton')}
      </button>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { X } from 'lucide-react';
import { useConfigurator } from '../../context/ConfiguratorContext';
import { useLanguage } from '../../context/LanguageContext';
import { threadColours } from '../../data/configuratorConstants';

const ZONE_CONFIG = {
  top: {
    options: ['smooth', 'alcantara', 'perforated', 'carbon'],
    action: 'SET_TOP',
    getCurrentValue: (state) => state.topMaterial,
  },
  bottom: {
    options: ['smooth', 'alcantara', 'perforated', 'carbon'],
    action: 'SET_BOTTOM',
    getCurrentValue: (state) => state.bottomMaterial,
  },
  sides: {
    options: ['smooth', 'alcantara', 'perforated'],
    action: 'SET_SIDE',
    getCurrentValue: (state) => state.sideMaterial,
  },
  thread: {
    options: threadColours,
    action: 'SET_THREAD',
    getCurrentValue: (state) => state.threadColour,
    type: 'colour',
  },
  hub: {
    options: ['factory', 'flat', 'full'],
    action: 'SET_WHEEL_SHAPE',
    getCurrentValue: (state) => state.wheelShape,
  },
};

function useIsMobile() {
  const [isMobile, setIsMobile] = useState(() => window.innerWidth < 768);
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);
  return isMobile;
}

export default function ZonePopover({ zone, onClose }) {
  const { state, dispatch } = useConfigurator();
  const { t } = useLanguage();
  const isMobile = useIsMobile();
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    requestAnimationFrame(() => setVisible(true));
  }, []);

  useEffect(() => {
    const handleKey = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, [onClose]);

  const config = ZONE_CONFIG[zone];
  if (!config) return null;
  if (!isMobile) return null;

  const currentValue = config.getCurrentValue(state);

  const handleSelect = (opt) => {
    dispatch({ type: config.action, value: opt });
    onClose();
  };

  const zoneLabel = zone === 'hub' ? t('configurator', 'wheelType') : t('configurator', zone);

  return (
    <div
      className="fixed inset-0 z-50"
      style={{ background: visible ? 'rgba(0,0,0,0.45)' : 'rgba(0,0,0,0)', transition: 'background 0.25s' }}
      onClick={onClose}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          transform: visible ? 'translateY(0)' : 'translateY(100%)',
          transition: 'transform 0.3s cubic-bezier(0.32, 0.72, 0, 1)',
        }}
        className="bg-white rounded-t-2xl p-6 shadow-2xl"
      >
        <div className="w-10 h-1 bg-gray-200 rounded-full mx-auto mb-5" />
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-extrabold text-sm uppercase tracking-widest text-black">
            {zoneLabel}
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-black transition-colors">
            <X size={18} />
          </button>
        </div>
        {config.type === 'colour' ? (
          <div className="flex flex-wrap gap-3 pb-2">
            {config.options.map((opt) => (
              <button
                key={opt}
                onClick={() => handleSelect(opt)}
                title={opt.charAt(0).toUpperCase() + opt.slice(1)}
                className={`w-10 h-10 rounded-full border-2 transition-transform hover:scale-110
                  ${currentValue === opt ? 'border-black scale-110' : opt === 'white' ? 'border-gray-300' : 'border-transparent'}`}
                style={{ backgroundColor: opt }}
              />
            ))}
          </div>
        ) : (
          <div className="flex flex-wrap gap-2 pb-2">
            {config.options.map((opt) => (
              <button
                key={opt}
                onClick={() => handleSelect(opt)}
                className={`px-5 py-2.5 rounded-xl border text-sm capitalize font-semibold transition-all
                  ${currentValue === opt
                    ? 'bg-black text-white border-black'
                    : 'bg-white text-black border-gray-200 hover:border-black'
                  }`}
              >
                {t('configurator', opt)}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { render, screen } from "@testing-library/react";
import WheelPreview from "../WheelPreview";
import { ConfiguratorProvider } from "../../../context/ConfiguratorContext";
import { LanguageProvider } from "../../../context/LanguageContext";

// Full provider stack required by WheelPreview
function Providers({ children }) {
  return (
    <LanguageProvider>
      <ConfiguratorProvider>{children}</ConfiguratorProvider>
    </LanguageProvider>
  );
}

// Pre-seeds localStorage before ConfiguratorProvider mounts so its `init`
// function hydrates with the desired state.
function seedState(partial) {
  const defaults = {
    selectedModel: "audi",
    wheelShape: "factory",
    topMaterial: "smooth",
    sideMaterial: "smooth",
    bottomMaterial: "smooth",
    ringEnabled: false,
    ringColour: "red",
    threadColour: "black",
  };
  localStorage.setItem(
    "configurator_state",
    JSON.stringify({ ...defaults, ...partial })
  );
}

describe("WheelPreview", () => {
  beforeEach(() => localStorage.clear());

  // ── Fallback ─────────────────────────────────────────────────────────────────

  it('renders "Coming Soon" when no model is selected (default state)', () => {
    // Arrange — localStorage is empty; ConfiguratorProvider uses initialState
    //           where selectedModel is null → non-audi branch
    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert
    expect(screen.getByText(/coming soon/i)).toBeInTheDocument();
  });

  it('renders "Coming Soon" when a non-audi model is selected', () => {
    // Arrange
    seedState({ selectedModel: "bmw" });

    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert
    expect(screen.getByText(/coming soon/i)).toBeInTheDocument();
  });

  // ── Audi model selected ───────────────────────────────────────────────────────

  it("does not render the Coming Soon fallback when audi is selected", () => {
    // Arrange
    seedState({ selectedModel: "audi" });

    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert
    expect(screen.queryByText(/coming soon/i)).not.toBeInTheDocument();
  });

  // ── Ring layer visibility (Observer pattern) ──────────────────────────────────

  it("ring image has opacity 1 when ringEnabled is true and colour matches", () => {
    // Arrange
    seedState({ ringEnabled: true, ringColour: "red" });

    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert
    const ringImg = document.querySelector(
      'img[src="/wheels/audi/ring/ring_red.png"]'
    );
    expect(ringImg).not.toBeNull();
    expect(ringImg.style.opacity).toBe("1");
  });

  it("ring image has opacity 0 when ringEnabled is false", () => {
    // Arrange
    seedState({ ringEnabled: false, ringColour: "red" });

    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert
    const ringImg = document.querySelector(
      'img[src="/wheels/audi/ring/ring_red.png"]'
    );
    expect(ringImg).not.toBeNull();
    expect(ringImg.style.opacity).toBe("0");
  });

  // ── Material layer visibility ─────────────────────────────────────────────────

  it("selected top material layer has opacity 1, inactive layers have opacity 0", () => {
    // Arrange
    seedState({ wheelShape: "factory", topMaterial: "carbon" });

    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert
    const active = document.querySelector(
      'img[src="/wheels/audi/factory/top_carbon.png"]'
    );
    const inactive = document.querySelector(
      'img[src="/wheels/audi/factory/top_alcantara.png"]'
    );
    expect(active.style.opacity).toBe("1");
    expect(inactive.style.opacity).toBe("0");
  });

  it("wheel shape base image switches correctly between factory / full / flat", () => {
    // Arrange
    seedState({ wheelShape: "full" });

    // Act
    render(
      <Providers>
        <WheelPreview />
      </Providers>
    );

    // Assert — full base is visible, factory and flat are not
    const fullBase = document.querySelector(
      'img[src="/wheels/audi/full/audi_full_base.png"]'
    );
    const factoryBase = document.querySelector(
      'img[src="/wheels/audi/factory/audi_factory_base.png"]'
    );
    expect(fullBase.style.opacity).toBe("1");
    expect(factoryBase.style.opacity).toBe("0");
  });
});

import { createContext, useContext, useState, useEffect } from "react";
const AuthContext = createContext();
export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch {
        localStorage.removeItem("user");
      }
    }
    setAuthLoading(false);
  }, []);
  const login = async (email, password) => {
    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok)
        throw new Error(data.error || data.message || "Login failed");
      localStorage.setItem("user", JSON.stringify(data.user));
      setUser(data.user);
      return { success: true, user: data.user };
    } catch (err) {
      return { success: false, error: err.message };
    }
  };
  const register = async (name, email, password) => {
    try {
      const res = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ name, email, password }),
      });
      const data = await res.json();
      if (!res.ok)
        throw new Error(data.error || data.message || "Registration failed");
      localStorage.setItem("user", JSON.stringify(data.user));
      setUser(data.user);
      return { success: true };
    } catch (err) {
      return { success: false, error: err.message };
    }
  };
  const logout = () => {
    fetch("/api/auth/logout", { method: "POST", credentials: "include" }).catch(() => {});
    localStorage.removeItem("user");
    setUser(null);
  };
  const loginWithToken = (userData) => {
    localStorage.setItem("user", JSON.stringify(userData));
    setUser(userData);
  };
  return (
    <AuthContext.Provider
      value={{ user, authLoading, login, register, logout, loginWithToken, isAdmin: user?.role === "admin" }}
    >
      {children}
    </AuthContext.Provider>
  );
}
export function useAuth() {
  return useContext(AuthContext);
}

import { createContext, useContext, useReducer, useEffect } from 'react';

const initialState = {
  selectedModel: null,
  wheelShape: 'factory',
  topMaterial: 'smooth',
  sideMaterial: 'smooth',
  bottomMaterial: 'smooth',
  ringEnabled: false,
  ringColour: 'red',  
  threadColour: 'red',
};

function configuratorReducer(state, action) {
  switch (action.type) {
    case 'SET_MODEL':
      return { ...state, selectedModel: action.value };
    case 'SET_WHEEL_SHAPE':
      return { ...state, wheelShape: action.value };
    case 'SET_TOP':
      return { ...state, topMaterial: action.value };
    case 'SET_SIDE':
      return { ...state, sideMaterial: action.value };
    case 'SET_BOTTOM':
      return { ...state, bottomMaterial: action.value };
    case 'SET_RING':
      return { ...state, ringEnabled: action.value };
    case 'SET_RING_COLOUR':                              
      return { ...state, ringColour: action.value };
    case 'SET_THREAD':
      return { ...state, threadColour: action.value };
    case 'RESET':
      return initialState;
    default:
      return state;
  }
}

const ConfiguratorContext = createContext(null);

const init = (initial) => {
  try {
    const saved = localStorage.getItem('configurator_state');
    return saved ? JSON.parse(saved) : initial;
  } catch (err) {
    console.error("Failed to parse configurator state", err);
    return initial;
  }
};

export function ConfiguratorProvider({ children }) {
  const [state, dispatch] = useReducer(configuratorReducer, initialState, init);

  useEffect(() => {
    localStorage.setItem('configurator_state', JSON.stringify(state));
  }, [state]);

  return (
    <ConfiguratorContext.Provider value={{ state, dispatch }}>
      {children}
    </ConfiguratorContext.Provider>
  );
}

export function useConfigurator() {
  return useContext(ConfiguratorContext);
}

import { createContext, useContext, useState } from "react";
import { translations } from "../data/translations";
const LanguageContext = createContext();
export function LanguageProvider({ children }) {
  const [lang, setLang] = useState("en");
  const toggleLanguage = () => {
    setLang((prev) => (prev === "en" ? "bs" : "en"));
  };
  const t = (section, key) => {
    return translations[lang][section]?.[key] || key;
  };
  return (
    <LanguageContext.Provider value={{ lang, toggleLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}
export function useLanguage() {
  return useContext(LanguageContext);
}

import { createContext, useContext, useState, useEffect } from "react";
const ShopContext = createContext();

export function ShopProvider({ children }) {
  const [cart, setCart] = useState([]);
  const [productsList, setProductsList] = useState([]);
  useEffect(() => {
    const storedCart = localStorage.getItem("cart");
    if (storedCart) {
      setCart(JSON.parse(storedCart));
    }
    fetch("/api/products")
      .then((res) => res.json())
      .then((data) => setProductsList(data))
      .catch((err) => console.error("Failed to load products", err));
  }, []);
  useEffect(() => {
    localStorage.setItem("cart", JSON.stringify(cart));
  }, [cart]);
  const addToCart = (product) => {
    if (product.is_in_stock === false) return;
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item,
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };
  const removeFromCart = (productId) => {
    setCart((prev) => prev.filter((item) => item.id !== productId));
  };
  const clearCart = () => setCart([]);
  const addProduct = async (product) => {
    try {
      const response = await fetch("/api/products", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(product),
      });
      if (!response.ok) throw new Error("Failed to add product");
      const newProduct = await response.json();
      setProductsList((prev) => [...prev, newProduct]);
    } catch (err) {
      console.error(err);
    }
  };
  const updateProduct = async (id, productData) => {
    try {
      const response = await fetch(`/api/products/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(productData),
      });
      if (!response.ok) throw new Error("Failed to update product");
      const updatedProduct = await response.json();
      setProductsList((prev) => prev.map((p) => p.id === id ? updatedProduct : p));
    } catch (err) {
      console.error(err);
    }
  };
  const deleteProduct = async (id) => {
    try {
      await fetch(`/api/products/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      setProductsList((prev) => prev.filter((p) => p.id !== id));
    } catch (err) {
      console.error(err);
    }
  };
  const placeOrder = async (user, shippingDetails) => {
    try {
      const response = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          userEmail: user.email,
          shipping: shippingDetails,
          items: cart.map((item) => ({ id: item.id, quantity: item.quantity })),
        }),
      });
      if (!response.ok) throw new Error("Order failed");
      clearCart();
      return true;
    } catch (err) {
      console.error(err);
      return false;
    }
  };
  const sendMessage = async (contactData) => {
    try {
      await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(contactData),
      });
      return true;
    } catch (err) {
      console.error(err);
      return false;
    }
  };
  const submitInquiry = async (inquiryData) => {
    try {
      const response = await fetch("/api/configurator-inquiries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(inquiryData),
      });
      return response.ok;
    } catch (err) {
      console.error(err);
      return false;
    }
  };
  return (
    <ShopContext.Provider
      value={{
        cart,
        addToCart,
        removeFromCart,
        clearCart,
        placeOrder,
        products: productsList,
        addProduct,
        updateProduct,
        deleteProduct,
        sendMessage,
        submitInquiry,
      }}
    >
      {children}
    </ShopContext.Provider>
  );
}
export function useShop() {
  return useContext(ShopContext);
}

